}
```

### Close Upload

```
{
    query:`
        mutation close($input: CloseUploadInput!){
            closeUpload(input: $input) {
                message
            }
        }
    `,
    variables:{ input: {
      "id": "BATCH ID",
     "multipart": "MultiPart ID returned in 'multipart' field from create endpoint"
    "parts": [{ Part Object returned by AWS API - Etag & PartNumber }]
   }}
